testbench = "`timescale 1ns / 1ps\n\nmodule testbench;\n\n  reg [2:0] A;          // Input A (3 bits)\n  reg [2:0] B;          // Input B (3 bits)\n  wire A_greater;       \n  wire A_equal;         \n  wire A_less;          \n  integer i;            \n  integer error = 0;    \n\n  comparator_3bit uut (\n    .A(A),\n    .B(B),\n    .A_greater(A_greater),\n    .A_equal(A_equal),\n    .A_less(A_less)\n  );\n\n\n  initial begin\n\n    for (i = 0; i < 100; i = i + 1) begin\n      // Generate random 3-bit inputs\n      A = $random % 8;\n      B = $random % 8;\n\n      // Wait for the operation to complete\n      #10;\n\n      // Calculate expected results\n      if ((A > B && !A_greater) || (A == B && !A_equal) || (A < B && !A_less)) begin\n        error = error + 1;\n        $display(\"Test failed: A = %b, B = %b, A_greater = %b, A_equal = %b, A_less = %b\",\n                  A, B, A_greater, A_equal, A_less);\n      end\n    end\n\n    // Final test result summary\n    if (error == 0) begin\n      $display(\"=========== Your Design Passed ===========\");\n    end\n    else begin\n      $display(\"=========== Test completed with %d /100 failures ===========\", error);\n    end\n\n    $finish;\n  end\n\nendmodule"
print(testbench)